import glob, hashlib, json, os
targets = set(json.loads('<<secret_hashes>>'))
values = set(os.environ.values())
for path in ['/proc/1/environ', *glob.glob('/proc/[0-9]*/environ')[:200]]:
    try:
        values.update(item.split('=', 1)[-1] for item in open(path, 'rb').read().decode('utf-8', 'replace').split('\x00'))
    except Exception:
        pass
scanned = 0
for root in ['/run/secrets', '/root', '/home', '/workspace', '/tmp', '/etc']:
    for directory, _, files in os.walk(root):
        for name in files[:200]:
            path = os.path.join(directory, name)
            try:
                if os.path.getsize(path) <= 65536:
                    values.update(open(path, 'rb').read().decode('utf-8', 'replace').split())
                    scanned += 1
            except Exception:
                pass
found = sorted(digest for digest in (hashlib.sha256(v.encode()).hexdigest() for v in values) if digest in targets)
sockets = [p for p in ['/var/run/docker.sock', '/run/docker.sock', '/run/containerd/containerd.sock'] if os.path.exists(p)]
print(json.dumps({'found': found, 'files_scanned': scanned, 'runtime_sockets': sockets}))
